import{_ as l,a0 as t,w as o,s as d,ao as c,I as p,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"用 Linux 命令列解決 Wordle 問題 | LCTT x X-CMD","titleTemplate":false,"description":"用 Linux 命令列解決 Wordle 問題 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"用 Linux 命令列解決 Wordle 問題 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"用 Linux 命令列解決 Wordle 問題 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220116 Solve Wordle using the Linux command line","title":"用 Linux 命令列解決 Wordle 問題","tag":"202202","desc":""},"relativePath":"202202/20220116 Solve Wordle using the Linux command line.md","filePath":"[post].md"}'),r={name:"202202/20220116 Solve Wordle using the Linux command line.md"};function g(u,s,h,k,b,m){const a=t("Link");return o(),d("div",null,[s[15]||(s[15]=c(`<h1 id="用-linux-命令列解決-wordle-問題" tabindex="-1">用 Linux 命令列解決 Wordle 問題 <a class="header-anchor" href="#用-linux-命令列解決-wordle-問題" aria-label="Permalink to “用 Linux 命令列解決 Wordle 問題”">​</a></h1><blockquote><p>使用 Linux 的 grep 和 fgrep 命令來贏得你最喜歡的基於單詞的猜測遊戲。</p></blockquote><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/linux_keyboard_desktop.png?itok=I2nGw78_" alt="Linux keys on the keyboard for a desktop computer" title="Linux keys on the keyboard for a desktop computer"></p><p>我最近有點迷戀上了一個在線單詞猜謎遊戲，在這個遊戲中，你有六次機會來猜一個隨機的五個字母的單詞。這個詞每天都在變化，而且你每天只能玩一次。每次猜測後，你猜測中的每個字母都會被高亮顯示：灰色表示該字母沒有出現在神秘單詞中，黃色表示該字母出現在單詞中，但不在那個位置，綠色表示該字母出現在單詞中的那個正確位置。</p><p>下面是你如何使用 Linux 命令列來幫助你玩像 Wordle 這樣的猜測遊戲。我用這個方法來幫助我解決 1 月 6 日的謎題：</p><h3 id="第一次嘗試" tabindex="-1">第一次嘗試 <a class="header-anchor" href="#第一次嘗試" aria-label="Permalink to “第一次嘗試”">​</a></h3><p>Linux 系統在 <code>/usr/share/dict/words</code> 文件中保存了一個單詞詞典。這是一個很長的純文本文件。我的系統的單詞文件裏有超過 479,800 個條目。該文件既包含純文本，也包含專有名詞（名字、地點等等）。</p><p>為了開始我的第一次猜測，我只想得到一個長度正好是五個字母的純文本詞的列表。要做到這一點，我使用這個 <code>grep</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^[a-z][a-z][a-z][a-z][a-z]$&#39; /usr/share/dict/words &gt; myguess</span></span></code></pre></div><p><code>grep</code> 命令使用正則表達式來進行搜索。你可以用正則表達式做很多事情，但為了幫助我解決 Wordle 問題，我只需要基本的東西。<code>^</code> 表示一行的開始，<code>$</code> 表示一行的結束。在兩者之間，我指定了五個 <code>[a-z]</code> 的實例，表示從 a 到 z 的任何小寫字母。</p><p>我還可以使用 <code>wc</code> 命令來查看我的可能單詞列表，“只有” 15,000 個單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l myguess</span></span>
<span class="line"><span>15034 myguess</span></span></code></pre></div><p>從這個列表中，我隨機挑選了一個五個字母的單詞：<code>acres</code>。<code>a</code> 被設置為黃色，意味着該字母存在於神秘單詞的某處，但不在第一位置。其他字母是灰色的，所以我知道它們並不存在於今天的單詞中。</p><p><img src="https://opensource.com/sites/default/files/acres.png" alt="acres word attempt" title="acres word attempt"></p><h3 id="第二次嘗試" tabindex="-1">第二次嘗試 <a class="header-anchor" href="#第二次嘗試" aria-label="Permalink to “第二次嘗試”">​</a></h3><p>對於我的下一個猜測，我想得到一個包含 <code>a</code> 的所有單詞的列表，但不是在第一位置。我的列表也不應該包括字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code>。讓我們把這個問題分解成幾個步驟。</p><p>為了得到所有帶 a 的單詞的列表，我使用 <code>fgrep</code>（固定字符串 grep）命令。<code>fgrep</code> 命令也像 <code>grep</code> 一樣搜索文本，但不使用正則表達式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess &gt; myguess2</span></span></code></pre></div><p>這使我的下一個猜測的可能列表從 15,000 個字下降到 6,600 個字：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span> 15034 myguess</span></span>
<span class="line"><span>  6634 myguess2</span></span>
<span class="line"><span> 21668 total</span></span></code></pre></div><p>但是這個單詞列表中的第一個位置也有字母 <code>a</code>，這是我不想要的。遊戲已經表明字母 <code>a</code> 存在於其他位置。我可以用 <code>grep</code> 修改我的命令，以尋找在第一個位置包含其他字母的詞。這就把我可能的猜測縮小到了 5500 個單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess | grep &#39;^[b-z]&#39; &gt; myguess2</span></span>
<span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span> 15034 myguess</span></span>
<span class="line"><span>  5566 myguess2</span></span>
<span class="line"><span> 20600 total</span></span></code></pre></div><p>但我知道這個神秘的詞也不包括字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code>。我可以使用另一個 <code>grep</code> 命令，在搜索中省略這些字母：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fgrep a myguess | grep &#39;^[b-z]&#39; | grep -v &#39;[cres]&#39; &gt; myguess2</span></span>
<span class="line"><span>$ wc -l myguess myguess2</span></span>
<span class="line"><span>15034 myguess</span></span>
<span class="line"><span> 1257 myguess2</span></span>
<span class="line"><span>16291 total</span></span></code></pre></div><p><code>-v</code> 選項意味着反轉搜索，所以 <code>grep</code> 將只返回不符合正則表達式 <code>[cres]</code> 或單列字母 <code>c</code>、<code>r</code>、<code>e</code> 或 <code>s</code> 的行。有了這個額外的 <code>grep</code> 命令，我把下一個猜測的範圍大大縮小到只有 1200 個可能的單詞，這些單詞在某處有一個 <code>a</code>，但不在第一位置，並且不包含 <code>c</code>、<code>r</code>、<code>e</code>、或 <code>s</code>。</p><p>在查看了這個列表後，我決定嘗試一下 <code>balmy</code> 這個詞。</p><p><img src="https://opensource.com/sites/default/files/balmy.png" alt="balmy word attempt" title="balmy word attempt"></p><h3 id="第三次嘗試" tabindex="-1">第三次嘗試 <a class="header-anchor" href="#第三次嘗試" aria-label="Permalink to “第三次嘗試”">​</a></h3><p>這一次，字母 <code>b</code> 和 <code>a</code> 被高亮顯示為綠色，意味着我把這些字母放在了正確的位置。字母 <code>l</code> 是黃色的，所以這個字母存在於單詞的其他地方，但不是在那個位置。字母 <code>m</code> 和 <code>y</code> 是灰色的，所以我可以從我的下一個猜測中排除這些。</p><p>為了確定下一個可能的單詞列表，我可以使用另一組 <code>grep</code> 命令。我知道這個詞以 <code>ba</code> 開頭，所以我可以從這裏開始搜索：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba&#39; myguess2 &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>77 myguess3</span></span></code></pre></div><p>這隻有 77 個詞! 我可以進一步縮小範圍，尋找除第三位外還包含字母 <code>l</code> 的詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>61 myguess3</span></span></code></pre></div><p>方括號 <code>[^l]</code> 內的 <code>^</code> 表示不是這個字母列表，即不是字母 <code>l</code>。這使我的可能單詞列表達到 61 個，並非所有的單詞都包含字母 <code>l</code>，我可以用另一個 <code>grep</code> 搜索來消除這些單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 | fgrep l &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>10 myguess3</span></span></code></pre></div><p>這些詞中有些可能包含字母 <code>m</code> 和 <code>y</code>，而這些字母並不在今天的神秘詞中。我可以再進行一次反轉 <code>grep</code> 搜索，將它們從我的猜測列表中刪除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ grep &#39;^ba[^l]&#39; myguess2 | fgrep l | grep -v &#39;[my]&#39; &gt; myguess3</span></span>
<span class="line"><span>$ wc -l myguess3</span></span>
<span class="line"><span>7 myguess3</span></span></code></pre></div><p>我的可能的單詞列表現在非常短，只有七個單詞!</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat myguess3</span></span>
<span class="line"><span>babul</span></span>
<span class="line"><span>bailo</span></span>
<span class="line"><span>bakal</span></span>
<span class="line"><span>bakli</span></span>
<span class="line"><span>banal</span></span>
<span class="line"><span>bauld</span></span>
<span class="line"><span>baulk</span></span></code></pre></div><p>我選擇 <code>banal</code> 作為我下一次猜測的可能的詞，而這恰好是正確的。</p><p><img src="https://opensource.com/sites/default/files/banal.png" alt="banal word attempt" title="banal word attempt"></p><h3 id="正則表達式的力量" tabindex="-1">正則表達式的力量 <a class="header-anchor" href="#正則表達式的力量" aria-label="Permalink to “正則表達式的力量”">​</a></h3><p>Linux 的命令列提供了強大的工具來幫助你完成實際工作。<code>grep</code> 和 <code>fgrep</code> 命令在掃描單詞列表方面提供了極大的靈活性。對於一個基於單詞的猜測遊戲，<code>grep</code> 幫助識別了一個包含 15000 個可能的單詞的列表。在猜測並知道哪些字母出現在神秘的單詞中，哪些沒有，<code>grep</code> 和 <code>fgrep</code> 幫助將選項縮小到 1200 個單詞，然後只剩下 7 個單詞。這就是命令列的力量。</p><hr>`,44)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/22/1/word-game-linux-command-line"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/22/1/word-game-linux-command-line",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const C=l(r,[["render",g]]);export{x as __pageData,C as default};
